@pytest.mark.parametrize('payload', [b'one',b'x'*100,b''])
def test_observed_records(payload):
    import io
    class Unknown:
        def __init__(self,body): self.stream=io.BytesIO(body)
        def read(self,size=-1): return self.stream.read(size)
    request=httpx.Request('POST','http://case.invalid/upload',data={'note':'keep'},files={'known':('known.txt',b'known'),'unknown':('unknown.bin',Unknown(payload))})
    body=request.read()
    assert request.headers.get('transfer-encoding')=='chunked'
    assert 'content-length' not in request.headers
    assert b'name="unknown"; filename="unknown.bin"' in body
    assert b'\r\n\r\n'+payload+b'\r\n' in body and b'known' in body and b'keep' in body

def get(self, key: str, default: typing.Any = None) -> typing.Any:
    """
    Return a header value. If multiple occurrences of the header occur
    then concatenate them together with commas.
    """
    try:
        return self[key]
    except KeyError:
        return default

def _prepare(self, default_headers: dict[str, str]) -> None:
    for key, value in default_headers.items():
        # Ignore Transfer-Encoding if the Content-Length has been set explicitly.
        if key.lower() == "transfer-encoding" and "Content-Length" in self.headers:
            continue
        self.headers.setdefault(key, value)

    auto_headers: list[tuple[bytes, bytes]] = []

    has_host = "Host" in self.headers
    has_content_length = (
        "Content-Length" in self.headers or "Transfer-Encoding" in self.headers
    )

    if not has_host and self.url.host:
        auto_headers.append((b"Host", self.url.netloc))
    if not has_content_length and self.method in ("POST", "PUT", "PATCH"):
        auto_headers.append((b"Content-Length", b"0"))

    self.headers = Headers(auto_headers + self.headers.raw)

@property
def encoding(self) -> str:
    """
    Header encoding is mandated as ascii, but we allow fallbacks to utf-8
    or iso-8859-1.
    """
    if self._encoding is None:
        for encoding in ["ascii", "utf-8"]:
            for key, value in self.raw:
                try:
                    key.decode(encoding)
                    value.decode(encoding)
                except UnicodeDecodeError:
                    break
            else:
                # The else block runs if 'break' did not occur, meaning
                # all values fitted the encoding.
                self._encoding = encoding
                break
        else:
            # The ISO-8859-1 encoding covers all 256 code points in a byte,
            # so will never raise decode errors.
            self._encoding = "iso-8859-1"
    return self._encoding

def __contains__(self, key: typing.Any) -> bool:
    header_key = key.lower().encode(self.encoding)
    return header_key in [key for _, key, _ in self._list]

def render_headers(self) -> bytes:
    if not hasattr(self, "_headers"):
        name = _format_form_param("name", self.name)
        self._headers = b"".join(
            [b"Content-Disposition: form-data; ", name, b"\r\n\r\n"]
        )

    return self._headers

def get_length(self) -> int:
    headers = self.render_headers()
    data = self.render_data()
    return len(headers) + len(data)

def render(self) -> typing.Iterator[bytes]:
    yield self.render_headers()
    yield self.render_data()

def render_data(self) -> bytes:
    if not hasattr(self, "_data"):
        self._data = to_bytes(self.value)

    return self._data

def iter_chunks(self) -> typing.Iterator[bytes]:
    for field in self.fields:
        yield b"--%s\r\n" % self.boundary
        yield from field.render()
        yield b"\r\n"
    yield b"--%s--\r\n" % self.boundary

def get_headers(self) -> dict[str, str]:
    content_length = self.get_content_length()
    content_type = self.content_type
    if content_length is None:
        return {"Transfer-Encoding": "chunked", "Content-Type": content_type}
    return {"Content-Length": str(content_length), "Content-Type": content_type}

def encode_multipart_data(
    data: RequestData, files: RequestFiles, boundary: bytes | None
) -> tuple[dict[str, str], MultipartStream]:
    multipart = MultipartStream(data=data, files=files, boundary=boundary)
    headers = multipart.get_headers()
    return headers, multipart

def _obfuscate_sensitive_headers(
    items: typing.Iterable[tuple[typing.AnyStr, typing.AnyStr]],
) -> typing.Iterator[tuple[typing.AnyStr, typing.AnyStr]]:
    for k, v in items:
        if to_str(k.lower()) in SENSITIVE_HEADERS:
            v = to_bytes_or_str("[secure]", match_type_of=v)
        yield k, v

